class Solution {
public:
    string longestWord(vector<string>& words) {
        unordered_set<string> wordSet(words.begin(), words.end());
        string best = "";
        for (const string& w : words) {
            bool valid = true;
            for (int k = 1; k < w.size(); ++k) {
                if (!wordSet.count(w.substr(0, k))) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                if (w.size() > best.size() || (w.size() == best.size() && w < best)) {
                    best = w;
                }
            }
        }
        return best;
    }
};

import java.util.*;

class Solution {
    public String longestWord(String[] words) {
        Set<String> wordSet = new HashSet<>(Arrays.asList(words));
        String best = "";
        for (String w : words) {
            boolean valid = true;
            for (int k = 1; k < w.length(); ++k) {
                if (!wordSet.contains(w.substring(0, k))) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                if (w.length() > best.length() || (w.length() == best.length() && w.compareTo(best) < 0)) {
                    best = w;
                }
            }
        }
        return best;
    }
}

