var longestWord = function(words) {
    const wordSet = new Set(words);
    let best = "";
    for (const w of words) {
        let valid = true;
        for (let k = 1; k < w.length; ++k) {
            if (!wordSet.has(w.slice(0, k))) {
                valid = false;
                break;
            }
        }
        if (valid) {
            if (w.length > best.length || (w.length === best.length && w < best)) {
                best = w;
            }
        }
    }
    return best;
};
